-- GAS-CP-R97-039 (v1.139.0) — Web Sales › Newsletters: issues, recipients with tracking, links, website subscribers, opt-outs, images
CREATE TABLE IF NOT EXISTS nl_issues (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, subject VARCHAR(200) NOT NULL DEFAULT '', preheader VARCHAR(200) NULL, lang VARCHAR(5) NOT NULL DEFAULT 'en', blocks MEDIUMTEXT NULL, audience TEXT NULL, status VARCHAR(12) NOT NULL DEFAULT 'draft', n_total INT NOT NULL DEFAULT 0, created_by INT NULL, created_name VARCHAR(120) NULL, queued_by INT NULL, queued_name VARCHAR(120) NULL, queued_at DATETIME NULL, sent_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_nl_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nl_sends (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id INT UNSIGNED NOT NULL, email VARCHAR(190) NOT NULL, name VARCHAR(160) NULL, contact_id INT NULL, company_id INT NULL, company VARCHAR(160) NULL, grp VARCHAR(20) NULL, token CHAR(24) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'queued', error VARCHAR(190) NULL, sent_at DATETIME NULL, opened_at DATETIME NULL, opens INT NOT NULL DEFAULT 0, clicked_at DATETIME NULL, clicks INT NOT NULL DEFAULT 0, unsub_at DATETIME NULL, UNIQUE KEY uq_nl_send (issue_id, email), UNIQUE KEY uq_nl_token (token), KEY idx_nl_queue (status, issue_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nl_links (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id INT UNSIGNED NOT NULL, n SMALLINT NOT NULL, url VARCHAR(600) NOT NULL, UNIQUE KEY uq_nl_link (issue_id, n)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nl_clicks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, send_id INT UNSIGNED NOT NULL, link_id INT UNSIGNED NOT NULL, at DATETIME NOT NULL, KEY idx_nl_click (send_id), KEY idx_nl_click_l (link_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nl_subs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, name VARCHAR(160) NULL, company VARCHAR(160) NULL, kind VARCHAR(20) NULL, topics VARCHAR(60) NOT NULL DEFAULT 'newsletter', lang VARCHAR(5) NULL, status VARCHAR(14) NOT NULL DEFAULT 'pending', token CHAR(24) NOT NULL, source VARCHAR(40) NULL, ip VARCHAR(64) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at DATETIME NULL, unsub_at DATETIME NULL, UNIQUE KEY uq_nl_sub (email), UNIQUE KEY uq_nl_sub_token (token)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nl_optout (email VARCHAR(190) NOT NULL PRIMARY KEY, reason VARCHAR(12) NOT NULL DEFAULT 'unsub', issue_id INT UNSIGNED NULL, at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nl_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_id INT UNSIGNED NOT NULL, token CHAR(24) NOT NULL, mime VARCHAR(40) NOT NULL, file VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_nl_img (token)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
